def cats(lst):
    tabs = []
    panes = []
    for i, (name, cards) in enumerate(lst):
        tabs.append('<button type="button" class="cat-t%s" role="tab" aria-selected="%s" data-i="%d"><span>%s</span><i></i></button>' % (' on' if i == 0 else '', 'true' if i == 0 else 'false', i, name))
        cs = ''.join('<div class="xb%s"><span class="mono">%s</span><b>%s</b><p>%s</p></div>' % (' on' if j == 0 else '', a, b, c) for j, (a, b, c) in enumerate(cards))
        panes.append('<div class="cat-p xb-grid%s" role="tabpanel" data-i="%d"%s>%s</div>' % (' on' if i == 0 else '', i, '' if i == 0 else ' hidden', cs))
    return '<div class="cat-tabs" role="tablist">' + ''.join(tabs) + '</div><div class="cat-ps">' + ''.join(panes) + '</div>'
